def topo_sort(graph):
    indegree = {u: 0 for u in graph}
    for u in graph:
        for v in graph[u]:
            indegree[v] = indegree.get(v, 0) + 1
    # düğümlerin hedeflerde olması için ekleyelim
    for u in graph:
        for v in graph[u]:
            indegree.setdefault(v, 0)

    # küçükten büyüğe sıralı küçük harfli düğümleri bir kuyruk olarak işleyelim
    import heapq
    heap = [u for u in indegree if indegree[u] == 0]
    heapq.heapify(heap)
    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in graph.get(u, []):
            indegree[v] -= 1
            if indegree[v] == 0:
                heapq.heappush(heap, v)
    if len(result) != len(indegree):
        raise ValueError("Graph contains a cycle")
    return result

